// Pokémon Muia: ponte tra el zogo e el server del multiplayer.
//
// Nel browser el motor del zogo no gà socket, quindi el zogo scrive file nella
// cartela dei salvataggi (OPFS) e questa pagina li inoltra al server via
// WebSocket, e fa el contrario con le risposte. El protocolo dei file xe
// descrito in Plugins/Voltseon's Multiplayer Solution/001_Base/004_VMS_Web_Bridge.rb
//
//   muia_ctl_<sigla>_<n>.bin    zogo -> pagina : "open" o "close"
//   muia_out_<sigla>_<n>.bin    zogo -> pagina : un messagio par el server
//   muia_in_<sigla>_<n>.bin     pagina -> zogo : un messagio dal server
//   muia_stato_<sigla>_<n>.bin  pagina -> zogo : svejo / conetendo / connesso /
//                                                 chiuso / erore: ...
// Ogni file finisse con "MUIA". Se el zogo no scrive, qua no se fa gnente.
//
// Anca (plugin "Muia Web"):
//   muia_txt_<sigla>_<n>.bin    zogo -> pagina : el zogo vol un testo (nome...):
//                                                 min \n max \n iniziale \n domanda
//   muia_txtris_<sigla>_<n>.bin pagina -> zogo : "ok\n<testo>" o "anula"
//   muia_esci_<sigla>_<n>.bin   zogo -> pagina : el zogador xe uscì dal zogo
//   muia_tasti_<sigla>_<n>.bin  zogo -> pagina : verzi la finestra dei tasti
//   muia_tastiris_<sigla>_<n>.bin pagina -> zogo : "ok" o "telefono"
//   muia_mappa_<sigla>_<n>.bin  zogo -> pagina : "1" libero sulla mapa, "0" no

type CartellaOpfs = any; // FileSystemDirectoryHandle (tipi non sempre presenti)

export interface OpzioniPonte {
  /** Dà la cartela dove el zogo scrive i salvataggi */
  trovaCartella: () => Promise<CartellaOpfs>;
  /** Indirizzo del WebSocket (wss://.../ws) */
  urlWebSocket: string;
  /** Indirizzo HTTP del server, par "svejarlo" se el dorme */
  urlSveglia: string;
  /** Ogni quanti ms controlar i file (default 25) */
  intervalloMs?: number;
  /** Secondi massimi par conetarse (default 150) */
  attesaMaxS?: number;
  log?: (...args: unknown[]) => void;
}

const FINE = new TextEncoder().encode("MUIA");
const PREFISSO = "muia_";
const IN_MAX_CODA = 40; // messagi dal server in attesa de scritura: oltre, i vecchi se perde
const VITA_FILE_IN_MS = 6000; // dopo, el file ricevù dal zogo xe tolto

const finisceConFine = (dati: Uint8Array): boolean => {
  if (dati.length < FINE.length) {
    return false;
  }
  for (let i = 0; i < FINE.length; i++) {
    if (dati[dati.length - FINE.length + i] !== FINE[i]) {
      return false;
    }
  }
  return true;
};

const numero8 = (n: number) => n.toString().padStart(8, "0");

interface Sessione {
  sigla: string;
  ws: WebSocket | null;
  connesso: boolean;
  chiusa: boolean;
  nStato: number;
  nIn: number;
  codaIn: Uint8Array[];
  scrivendo: boolean;
}

// ---- finestre della pagina in stile Pokémon ----------------------------
// Stesso font del zogo (Power Green, in Fonts/) e cornice come i messagi
// (bordo scuro, filo dorà, fondo bianco).
const FONT_MUIA = "data:font/ttf;base64,";

let stileMesso = false;
const mettiStile = () => {
  if (stileMesso) {
    return;
  }
  stileMesso = true;
  const st = document.createElement("style");
  st.textContent = `
@font-face { font-family: "MuiaPower"; src: url(${FONT_MUIA}) format("truetype"); }
.muia-fondo { position: fixed; inset: 0; z-index: 100000; background: rgba(0,0,0,.5);
  display: flex; align-items: center; justify-content: center; padding: 16px;
  touch-action: manipulation; }
.muia-box { width: 100%; max-width: 440px; box-sizing: border-box;
  max-height: 100%; overflow-y: auto;
  background: #5c5c6c; border: 4px solid #3c3434; border-radius: 14px; padding: 6px;
  box-shadow: inset 0 0 0 3px #f8d050, inset 0 -5px 0 3px #e8a030, 0 6px 0 rgba(0,0,0,.35); }
.muia-panel { background: #f8f8f8; border-radius: 8px; padding: 12px 14px 14px;
  font-family: "MuiaPower", monospace; font-size: 26px; line-height: 1.15;
  color: #505058; text-shadow: 2px 2px 0 #c8c8d0; -webkit-font-smoothing: none; }
.muia-titolo { margin: 0 0 10px; }
.muia-input { width: 100%; box-sizing: border-box; font: inherit; color: #303038;
  text-shadow: none; background: #fff; padding: 6px 10px; border: 3px solid #505058;
  border-radius: 6px; outline: none; -webkit-user-select: text; user-select: text;
  touch-action: manipulation; }
.muia-input:focus { border-color: #e83820; }
.muia-righe { display: flex; gap: 10px; margin-top: 12px; justify-content: flex-end; flex-wrap: wrap; }
.muia-btn { font: inherit; color: #505058; text-shadow: 2px 2px 0 #c8c8d0; background: #f8f8f8;
  border: 3px solid #505058; border-radius: 6px; padding: 2px 12px; cursor: pointer;
  touch-action: manipulation; }
.muia-btn:hover, .muia-btn:focus-visible { border-color: #e83820; outline: none; }
.muia-btn:hover::before, .muia-btn:focus-visible::before { content: "▶ "; color: #e83820; }
.muia-btn:disabled { opacity: .45; cursor: default; }
.muia-btn:disabled::before { content: none; }
.muia-tasti { width: 100%; border-collapse: collapse; font-size: 22px; }
.muia-tasti td { padding: 3px 2px; }
.muia-tasti .muia-btn { width: 100%; font-size: 21px; padding: 1px 4px; white-space: nowrap; }
.muia-box.muia-larga { max-width: 500px; }
.muia-nota { font-size: 18px; margin: 8px 0 0; }
`;
  document.head.appendChild(st);
};

// Mentre una finestra xe verta, i tasti va solo a ela (no al zogo): se ferma
// i eventi su window, prima che i rivi alla pagina o al motore.
let finestraAperta = false;
const bloccaTasti = (gestisci: (ev: KeyboardEvent) => void) => {
  const tasto = (ev: KeyboardEvent) => {
    ev.stopImmediatePropagation();
    if (ev.type === "keydown") {
      gestisci(ev);
    }
  };
  window.addEventListener("keydown", tasto, true);
  window.addEventListener("keypress", tasto, true);
  return () => {
    window.removeEventListener("keydown", tasto, true);
    window.removeEventListener("keypress", tasto, true);
  };
};

const creaFinestra = (titolo: string) => {
  mettiStile();
  const fondo = document.createElement("div");
  fondo.className = "muia-fondo";
  const box = document.createElement("div");
  box.className = "muia-box";
  const panel = document.createElement("form");
  panel.className = "muia-panel";
  const t = document.createElement("p");
  t.className = "muia-titolo";
  t.textContent = titolo;
  panel.appendChild(t);
  box.appendChild(panel);
  fondo.appendChild(box);
  document.body.appendChild(fondo);
  return { fondo, panel };
};

const bottone = (testo: string, tipo: "button" | "submit" = "button") => {
  const b = document.createElement("button");
  b.type = tipo;
  b.className = "muia-btn";
  b.textContent = testo;
  return b;
};

// ---- casela de testo vera (tastiera del PC o del telefono) -------------
interface RichiestaTesto {
  minimo: number;
  massimo: number;
  iniziale: string;
  domanda: string;
}

const mostraCasella = (r: RichiestaTesto): Promise<string | null> =>
  new Promise((resolve) => {
    finestraAperta = true;
    const { fondo, panel } = creaFinestra(r.domanda || "Scrivi");
    const input = document.createElement("input");
    input.type = "text";
    input.className = "muia-input";
    input.value = r.iniziale;
    if (r.massimo > 0) {
      input.maxLength = r.massimo;
    }
    input.autocomplete = "off";
    input.setAttribute("autocapitalize", "words");
    input.setAttribute("enterkeyhint", "done");
    input.spellcheck = false;
    const righe = document.createElement("div");
    righe.className = "muia-righe";
    const ok = bottone("Va ben", "submit");
    const anula = bottone("Anula");
    if (r.minimo <= 0) {
      righe.appendChild(anula);
    }
    righe.appendChild(ok);
    panel.append(input, righe);

    const valido = () => {
      const n = input.value.trim().length;
      return n >= Math.max(r.minimo, 0) && (r.massimo <= 0 || n <= r.massimo);
    };
    const aggiornaOk = () => {
      ok.disabled = !valido();
    };
    aggiornaOk();
    input.addEventListener("input", aggiornaOk);

    const sblocca = bloccaTasti((ev) => {
      if (ev.key === "Enter") {
        ev.preventDefault();
        conferma();
        return;
      }
      if (ev.key === "Escape" && r.minimo <= 0) {
        ev.preventDefault();
        fine(null);
        return;
      }
      if (document.activeElement !== input) {
        input.focus();
      }
    });
    const fine = (testo: string | null) => {
      sblocca();
      input.blur();
      fondo.remove();
      finestraAperta = false;
      resolve(testo);
    };
    const conferma = () => {
      if (valido()) {
        fine(input.value.trim());
      }
    };
    panel.addEventListener("submit", (ev) => {
      ev.preventDefault();
      conferma();
    });
    anula.addEventListener("click", () => fine(null));
    // Sul PC el cursor xe subito drento; sul telefono (iPhone) la tastiera
    // vien fora quando se toca la casela.
    setTimeout(() => {
      input.focus();
      input.select();
    }, 50);
  });

// ---- tasti della tastiera (browser sul PC) ------------------------------
// Do tasti par ogni azion, salvai nel browser. Invio conferma sempre. Anca
// le frecie passa da qua (prima le gestiva el motore, che le perdeva quando
// el zogo no gaveva el "focus", per esempio dopo la casela del nome). "Menu / Esci" verzi el menu se el zogador xe
// libero sulla mapa, se no torna indrio (el zogo lo dise coi file muia_mappa).
export type BotonPad =
  | "a" | "b" | "x" | "r3" | "up" | "down" | "left" | "right";
type Azion =
  | "su" | "zo" | "sinistra" | "destra"
  | "conferma" | "indietro" | "menu" | "funzione" | "rapido";
const AZIONI: [Azion, string][] = [
  ["su", "Su"],
  ["zo", "Zo"],
  ["sinistra", "Sinistra"],
  ["destra", "Destra"],
  ["conferma", "Conferma (A)"],
  ["indietro", "Indrio / Corer (B)"],
  ["menu", "Menu / Esci"],
  ["funzione", "Funzion"],
  ["rapido", "Menu rapido"],
];
const PREDEFINITI: Record<Azion, (string | null)[]> = {
  su: ["ArrowUp", null],
  zo: ["ArrowDown", null],
  sinistra: ["ArrowLeft", null],
  destra: ["ArrowRight", null],
  conferma: ["z", " "],
  indietro: ["x", "Backspace"],
  menu: ["Escape", null],
  funzione: ["Shift", null],
  rapido: ["d", null],
};
const CHIAVE_TASTI = "muia-tasti-v1";
const NON_SCEGLIBILI = new Set([
  "Enter",
  "Control", "Alt", "Meta", "AltGraph", "CapsLock", "Dead", "Unidentified",
]);

const copiaPredefiniti = () => {
  const c = {} as Record<Azion, (string | null)[]>;
  for (const [a] of AZIONI) {
    c[a] = [...PREDEFINITI[a]];
  }
  return c;
};

const caricaTasti = (): Record<Azion, (string | null)[]> => {
  const c = copiaPredefiniti();
  try {
    const salvati = JSON.parse(localStorage.getItem(CHIAVE_TASTI) ?? "null");
    if (salvati !== null && typeof salvati === "object") {
      for (const [a] of AZIONI) {
        const v = salvati[a];
        if (Array.isArray(v) && v.length === 2) {
          c[a] = v.map((k: unknown) => (typeof k === "string" ? k : null));
        }
      }
    }
  } catch (err) {
    // niente memoria del browser: tasti de base
  }
  return c;
};

let tasti = caricaTasti();
let mappaLibera = true;

// Conferma e le quatro direzion no pol restar senza tasti (se resteria
// bloccai): se le xe vode, se ghe rimete el tasto de base.
const sistemaVuoti = () => {
  // do giri: rimeter un tasto pol svodar un'altra azion
  for (const a of [
    "conferma", "su", "zo", "sinistra", "destra",
    "conferma", "su", "zo", "sinistra", "destra",
  ] as Azion[]) {
    if (tasti[a].every((x) => x === null)) {
      const k = PREDEFINITI[a][0] as string;
      for (const [b] of AZIONI) {
        tasti[b] = tasti[b].map((x) => (x === k ? null : x));
      }
      tasti[a][0] = k;
    }
  }
};

const salvaTasti = () => {
  try {
    localStorage.setItem(CHIAVE_TASTI, JSON.stringify(tasti));
  } catch (err) {
    // pazienza: valgono fin che la pagina xe verta
  }
};

/** Normalizza un tasto come main.ts (letere minuscole) */
export const nomeTasto = (ev: KeyboardEvent) =>
  ev.key.length === 1 ? ev.key.toLowerCase() : ev.key;

const mostraTasto = (k: string | null) => {
  if (k === null) {
    return "-";
  }
  const nomi: Record<string, string> = {
    " ": "Spazio", Escape: "Esc", Backspace: "Back", Shift: "Shift",
    Tab: "Tab", Delete: "Canc", Insert: "Ins", Home: "Home", End: "Fine",
    PageUp: "Pag su", PageDown: "Pag giù",
    ArrowUp: "Frecia su", ArrowDown: "Frecia zo",
    ArrowLeft: "Frecia sx", ArrowRight: "Frecia dx",
  };
  return nomi[k] ?? (k.length === 1 ? k.toUpperCase() : k);
};

/** Boton del zogo par un tasto de la tastiera (o undefined se no xe usà) */
export const bottonePerTasto = (k: string): BotonPad | undefined => {
  if (k === "Enter") {
    return "a";
  }
  for (const [a] of AZIONI) {
    if (!tasti[a].includes(k)) {
      continue;
    }
    switch (a) {
      case "su":
        return "up";
      case "zo":
        return "down";
      case "sinistra":
        return "left";
      case "destra":
        return "right";
      case "conferma":
        return "a";
      case "indietro":
        return "b";
      case "menu":
        return mappaLibera ? "x" : "b";
      case "funzione":
        return "x";
      case "rapido":
        return "r3";
    }
  }
  return undefined;
};

const soloTouch = () =>
  window.matchMedia("(hover: none) and (pointer: coarse)").matches;

// Finestra par cambiar i tasti. Torna "ok", o "telefono" se no ghe xe tastiera.
const mostraTasti = (): Promise<string> =>
  new Promise((resolve) => {
    if (soloTouch()) {
      resolve("telefono");
      return;
    }
    finestraAperta = true;
    const { fondo, panel } = creaFinestra("Tasti (do par azion)");
    fondo.firstElementChild?.classList.add("muia-larga");
    const tabella = document.createElement("table");
    tabella.className = "muia-tasti";
    let attesa: { a: Azion; i: number; b: HTMLButtonElement } | null = null;
    const bottoni: HTMLButtonElement[][] = [];

    const ridisegna = () => {
      AZIONI.forEach(([a], r) => {
        bottoni[r].forEach((b, i) => {
          b.textContent =
            attesa !== null && attesa.a === a && attesa.i === i
              ? "schicia..."
              : mostraTasto(tasti[a][i]);
        });
      });
    };
    for (const [a, nome] of AZIONI) {
      const tr = document.createElement("tr");
      const td = document.createElement("td");
      td.textContent = nome;
      tr.appendChild(td);
      const riga: HTMLButtonElement[] = [];
      for (let i = 0; i < 2; i++) {
        const cella = document.createElement("td");
        cella.style.width = "30%";
        const b = bottone("");
        b.addEventListener("click", () => {
          attesa = { a, i, b };
          ridisegna();
        });
        cella.appendChild(b);
        tr.appendChild(cella);
        riga.push(b);
      }
      bottoni.push(riga);
      tabella.appendChild(tr);
    }
    const nota = document.createElement("p");
    nota.className = "muia-nota";
    nota.textContent =
      "Clicca un tasto e schicia quel novo. Canc lo toe. Invio conferma sempre.";
    const righe = document.createElement("div");
    righe.className = "muia-righe";
    const rimeti = bottone("Rimeti come prima");
    const fato = bottone("Fato", "submit");
    righe.append(rimeti, fato);
    panel.append(tabella, nota, righe);
    ridisegna();

    const sblocca = bloccaTasti((ev) => {
      if (attesa === null) {
        if (ev.key === "Escape") {
          ev.preventDefault();
          fine();
        }
        return;
      }
      ev.preventDefault();
      const k = nomeTasto(ev);
      if (NON_SCEGLIBILI.has(k)) {
        return;
      }
      const { a, i } = attesa;
      if (k === "Delete" && !(a === "conferma" && i === 0)) {
        tasti[a][i] = null;
      } else {
        // el stesso tasto no pol far do robe: se toe da dove el iera
        for (const [b] of AZIONI) {
          tasti[b] = tasti[b].map((x) => (x === k ? null : x));
        }
        tasti[a][i] = k;
      }
      sistemaVuoti();
      attesa.b.focus();
      attesa = null;
      salvaTasti();
      ridisegna();
    });
    const fine = () => {
      sblocca();
      fondo.remove();
      finestraAperta = false;
      resolve("ok");
    };
    rimeti.addEventListener("click", () => {
      tasti = copiaPredefiniti();
      attesa = null;
      salvaTasti();
      ridisegna();
    });
    panel.addEventListener("submit", (ev) => {
      ev.preventDefault();
      if (attesa === null) {
        fine();
      }
    });
  });

// El zogador xe uscì dal zogo: se prova a serar la pagina, se no (el browser
// no lo permette se la pagina no xe stada verta da un script) se torna al sito.
const esciDalGioco = () => {
  try {
    window.close();
  } catch (err) {
    // gnente
  }
  setTimeout(() => {
    location.href = new URL("../", location.href).href;
  }, 300);
};

export const avviaPonte = (opz: OpzioniPonte) => {
  const log = opz.log ?? (() => {});
  const intervallo = opz.intervalloMs ?? 25;
  const attesaMax = (opz.attesaMaxS ?? 150) * 1000;
  let cartella: CartellaOpfs | null = null;
  let sessione: Sessione | null = null;
  let occupato = false;
  const creati = new Map<string, number>(); // file scriti da noi → quando
  const ricordaCreato = (nome: string) => creati.set(nome, Date.now());

  // Risposta della pagina al zogo (testo, tasti): un file che finisse con "MUIA"
  const scriviIn = async (dir: CartellaOpfs, nome: string, testo: string) => {
    try {
      const fh = await dir.getFileHandle(nome, { create: true });
      const w = await fh.createWritable();
      const corpo = new TextEncoder().encode(testo);
      const tutto = new Uint8Array(corpo.length + FINE.length);
      tutto.set(corpo, 0);
      tutto.set(FINE, corpo.length);
      await w.write(tutto);
      await w.close();
      ricordaCreato(nome);
    } catch (err) {
      log("ponte: risposta non scrita", nome, err);
    }
  };

  const scrivi = async (nome: string, dati: Uint8Array) => {
    const fh = await cartella.getFileHandle(nome, { create: true });
    const w = await fh.createWritable();
    const tutto = new Uint8Array(dati.length + FINE.length);
    tutto.set(dati, 0);
    tutto.set(FINE, dati.length);
    await w.write(tutto);
    await w.close();
    ricordaCreato(nome);
  };

  const scriviStato = async (s: Sessione, testo: string) => {
    s.nStato++;
    try {
      await scrivi(
        `${PREFISSO}stato_${s.sigla}_${numero8(s.nStato)}.bin`,
        new TextEncoder().encode(testo),
      );
    } catch (err) {
      log("ponte: stato non scrito", err);
    }
  };

  // Scrive in ordine i messagi arrivai dal server
  const svodaCodaIn = async (s: Sessione) => {
    if (s.scrivendo) {
      return;
    }
    s.scrivendo = true;
    try {
      while (s.codaIn.length > 0 && !s.chiusa) {
        const dati = s.codaIn.shift() as Uint8Array;
        s.nIn++;
        try {
          await scrivi(`${PREFISSO}in_${s.sigla}_${numero8(s.nIn)}.bin`, dati);
        } catch (err) {
          log("ponte: messagio non scrito", err);
        }
      }
    } finally {
      s.scrivendo = false;
    }
  };

  const chiudi = (s: Sessione, avisa: boolean) => {
    if (s.chiusa) {
      return;
    }
    s.chiusa = true;
    try {
      s.ws?.close();
    } catch (err) {
      // za serà
    }
    if (avisa) {
      void scriviStato(s, "chiuso");
    }
  };

  const apri = async (s: Sessione) => {
    const inizio = Date.now();
    await scriviStato(s, "svejo");
    // Prova a "svejar" el server: se el dorme, la prima richiesta lo fa partir
    const sveglia = () => {
      void fetch(opz.urlSveglia, { mode: "no-cors", cache: "no-store" }).catch(
        () => {},
      );
    };
    sveglia();
    while (!s.chiusa && !s.connesso) {
      if (Date.now() - inizio > attesaMax) {
        await scriviStato(s, "erore: server no risponde");
        chiudi(s, false);
        return;
      }
      await new Promise<void>((resolve) => {
        let finio = false;
        const fine = () => {
          if (!finio) {
            finio = true;
            resolve();
          }
        };
        let ws: WebSocket;
        try {
          ws = new WebSocket(opz.urlWebSocket);
        } catch (err) {
          setTimeout(fine, 3000);
          return;
        }
        ws.binaryType = "arraybuffer";
        s.ws = ws;
        ws.onopen = () => {
          if (s.chiusa) {
            ws.close();
            fine();
            return;
          }
          s.connesso = true;
          void scriviStato(s, "connesso");
          fine();
        };
        ws.onmessage = (ev) => {
          if (!(ev.data instanceof ArrayBuffer) || s.chiusa) {
            return;
          }
          s.codaIn.push(new Uint8Array(ev.data));
          while (s.codaIn.length > IN_MAX_CODA) {
            s.codaIn.shift();
          }
          void svodaCodaIn(s);
        };
        ws.onclose = () => {
          if (s.connesso && !s.chiusa) {
            s.connesso = false;
            chiudi(s, true); // conession cascà: el zogo ga da saverlo
          }
          // se no gaveva ancora verto: se riprova (server che se sta svegliando)
          setTimeout(fine, 3000);
        };
        ws.onerror = () => {
          // el "close" che vien dopo ghe pensa
        };
      });
      if (!s.connesso && !s.chiusa) {
        await scriviStato(s, "svejo");
        sveglia();
      }
    }
  };

  const cercaCartella = async (): Promise<CartellaOpfs | null> => {
    const saves = await opz.trovaCartella();
    const candidate: CartellaOpfs[] = [saves];
    for await (const [, handle] of saves.entries()) {
      if (handle.kind === "directory") {
        candidate.push(handle);
      }
    }
    for (const c of candidate) {
      for await (const [nome] of c.entries()) {
        if (/^muia_(ctl|txt|esci|tasti|mappa)_/.test(nome)) {
          return c;
        }
      }
    }
    return null;
  };

  const leggi = async (nome: string): Promise<Uint8Array | null> => {
    try {
      const fh = await cartella.getFileHandle(nome);
      const dati = new Uint8Array(await (await fh.getFile()).arrayBuffer());
      return finisceConFine(dati)
        ? dati.subarray(0, dati.length - FINE.length)
        : null;
    } catch (err) {
      return null;
    }
  };

  const giro = async () => {
    if (cartella === null) {
      cartella = await cercaCartella();
      if (cartella === null) {
        return;
      }
    }
    const nomi: string[] = [];
    for await (const [nome] of cartella.entries()) {
      if (nome.startsWith(PREFISSO)) {
        nomi.push(nome);
      }
    }
    nomi.sort();
    const adesso = Date.now();
    for (const nome of nomi) {
      const m = /^muia_(ctl|out|in|stato|txt|txtris|esci|tasti|tastiris|mappa)_([^_]+)_(\d+)\.bin$/.exec(nome);
      if (m === null) {
        continue;
      }
      const [, tipo, sigla, numero] = m;
      if (tipo === "esci") {
        await cartella.removeEntry(nome).catch(() => {});
        log("ponte: el zogador xe uscì");
        esciDalGioco();
        continue;
      }
      if (tipo === "mappa") {
        const dati = await leggi(nome);
        if (dati === null) {
          continue;
        }
        await cartella.removeEntry(nome).catch(() => {});
        mappaLibera = new TextDecoder().decode(dati) !== "0";
        continue;
      }
      if (tipo === "tasti") {
        if (finestraAperta) {
          continue;
        }
        const dati = await leggi(nome);
        if (dati === null) {
          continue;
        }
        await cartella.removeEntry(nome).catch(() => {});
        const dir = cartella;
        void mostraTasti().then((esito) =>
          scriviIn(dir, `${PREFISSO}tastiris_${sigla}_${numero}.bin`, esito),
        );
        continue;
      }
      if (tipo === "txt") {
        if (finestraAperta) {
          continue;
        }
        const dati = await leggi(nome);
        if (dati === null) {
          continue;
        }
        await cartella.removeEntry(nome).catch(() => {});
        const [minimo, massimo, iniziale, ...domanda] = new TextDecoder()
          .decode(dati)
          .split("\n");
        const dir = cartella;
        void mostraCasella({
          minimo: Number(minimo) || 0,
          massimo: Number(massimo) || 0,
          iniziale: iniziale ?? "",
          domanda: domanda.join(" "),
        }).then((testo) =>
          scriviIn(
            dir,
            `${PREFISSO}txtris_${sigla}_${numero}.bin`,
            testo === null ? "anula" : "ok\n" + testo,
          ),
        );
        continue;
      }
      if (tipo === "ctl") {
        const dati = await leggi(nome);
        if (dati === null) {
          continue;
        }
        await cartella.removeEntry(nome).catch(() => {});
        const comando = new TextDecoder().decode(dati);
        if (comando === "open") {
          if (sessione !== null) {
            chiudi(sessione, false);
          }
          sessione = {
            sigla,
            ws: null,
            connesso: false,
            chiusa: false,
            nStato: 0,
            nIn: 0,
            codaIn: [],
            scrivendo: false,
          };
          log("ponte: apro la sessione", sigla);
          void apri(sessione);
        } else if (comando === "close" && sessione?.sigla === sigla) {
          log("ponte: chiudo la sessione", sigla);
          // Prima manda i messagi che el zogo ga lassà (el "disconnect" par el
          // server), poi serra: i nomi dei file "ctl" i vien prima dei "out".
          for (const altro of nomi) {
            if (altro.startsWith(`${PREFISSO}out_${sigla}_`)) {
              const resto = await leggi(altro);
              if (resto !== null) {
                await cartella.removeEntry(altro).catch(() => {});
                if (sessione.ws !== null && sessione.connesso) {
                  sessione.ws.send(resto as BufferSource);
                }
              }
            }
          }
          const daSerar = sessione;
          sessione = null;
          setTimeout(() => chiudi(daSerar, false), 400);
        }
      } else if (tipo === "out") {
        if (sessione === null || sessione.sigla !== sigla || sessione.chiusa) {
          await cartella.removeEntry(nome).catch(() => {}); // vecio, de un'altra sessione
          continue;
        }
        const dati = await leggi(nome);
        if (dati === null) {
          continue;
        }
        await cartella.removeEntry(nome).catch(() => {});
        if (sessione.ws !== null && sessione.connesso) {
          sessione.ws.send(dati as BufferSource);
        }
      } else {
        // "in" e "stato" xe i nostri: se toe dopo un poco, tegnendo i ultimi stati
        const nato = creati.get(nome);
        if (nato === undefined) {
          // de una sessione precedente (pagina ricaricà): subito via
          await cartella.removeEntry(nome).catch(() => {});
        } else if (adesso - nato > VITA_FILE_IN_MS) {
          await cartella.removeEntry(nome).catch(() => {});
          creati.delete(nome);
        }
      }
    }
  };

  // A riposo (nissuna partìa online) se controla ogni mezo secondo, par no
  // consumar batteria; durante la partìa ogni "intervallo" (25 ms).
  // Sul PC un poco più spesso, par saver subito se Esc verzi el menu o torna indrio
  const RIPOSO_MS = soloTouch() ? 500 : 150;
  let ultimoGiro = 0;
  const timer = setInterval(async () => {
    if (occupato) {
      return;
    }
    if (sessione === null && Date.now() - ultimoGiro < RIPOSO_MS) {
      return;
    }
    occupato = true;
    ultimoGiro = Date.now();
    try {
      await giro();
    } catch (err) {
      log("ponte:", err);
    } finally {
      occupato = false;
    }
  }, intervallo);

  return () => {
    clearInterval(timer);
    if (sessione !== null) {
      chiudi(sessione, false);
    }
  };
};
